    ('挥霍', '他年轻时喜欢挥霍无度，后来才明白节俭的重要性。', 'phung phí', 'huī huò', '他年轻时喜欢挥霍无度，后来才明白节俭的重要性。', 'phung phí', 'huī huò', 'Tā niánqīng shí xǐhuan huīhuò wúdù, hòulái cái míngbái jiéjiǎn de zhòngyào xìng.', 'Khi còn trẻ anh ta thích phung phí vô độ, sau đó mới hiểu được tầm quan trọng của việc tiết kiệm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-d2cdbb9edb389105284516a3.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-4d29a2dc8fd258f1f5425563.mp3'),
    ('患者', '医生耐心地为每一位患者解答疑问。', 'người bệnh', 'huàn zhě', '医生耐心地为每一位患者解答疑问。', 'người bệnh', 'huàn zhě', 'Yīshēng nàixīn de wèi měi yī wèi huànzhě jiědá yíwèn.', 'Bác sĩ kiên nhẫn giải đáp thắc mắc cho từng bệnh nhân.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-9db4a3b37ed687cde721a1e9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-03c37994388b28f2cd9e088c.mp3'),
    ('悔恨', '他因错过了重要的机会而深感悔恨。', 'ân hận, hối lỗi', 'huǐ hèn', '他因错过了重要的机会而深感悔恨。', 'ân hận, hối lỗi', 'huǐ hèn', 'Tā yīn cuòguò le zhòngyào de jīhuì ér shēn gǎn huǐhèn.', 'Anh ấy cảm thấy rất hối hận vì đã bỏ lỡ cơ hội quan trọng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c3986e16dec139a17aecc84e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-3436c0c46ad2904baf3d483a.mp3'),
    ('恨不得', '看到朋友受伤，她恨不得马上帮忙治疗。', 'hận chẳng được', 'hèn bù dé', '看到朋友受伤，她恨不得马上帮忙治疗。', 'hận chẳng được', 'hèn bù dé', 'Kàn dào péngyǒu shòushāng, tā hèn bù dé mǎshàng bāngmáng zhìliáo.', 'Nhìn thấy bạn bị thương, cô ấy hận chẳng thể giúp chữa trị ngay lập tức.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-4817d23c316e9e8d58278d95.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-7605a4a2a1c6f50bebdc0808.mp3'),
    ('恍然大悟', '听完老师的解释，我才恍然大悟其中的道理。', 'bỗng nhiên tỉnh ngộ, hiểu ra', 'huǎng rán dà wù', '听完老师的解释，我才恍然大悟其中的道理。', 'bỗng nhiên tỉnh ngộ, hiểu ra', 'huǎng rán dà wù', 'Tīng wán lǎoshī de jiěshì, wǒ cái huǎngrán dà wù qízhōng de dàolǐ.', 'Nghe xong lời giảng giải của thầy, tôi mới bỗng nhiên hiểu ra lý lẽ bên trong.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-08fe75e7897337573f0cda70.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-37bf23b0550705aa846c0124.mp3'),
    ('忽略', '他忽略了细节，导致计划失败。', 'bỏ qua', 'hū lüè', '他忽略了细节，导致计划失败。', 'bỏ qua', 'hū lüè', 'Tā hūlüè le xìjié, dǎozhì jìhuà shībài.', 'Anh ta đã bỏ qua những chi tiết, dẫn đến kế hoạch thất bại.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-6e90ac940752ebf13ab2d29a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-0a7550cc7bc7484cef1c3594.mp3'),
    ('寒暄', '见面后，他们进行了简短的寒暄，气氛很友好。', 'tâm tình', 'hán xuān', '见面后，他们进行了简短的寒暄，气氛很友好。', 'tâm tình', 'hán xuān', 'Jiànmiàn hòu, tāmen jìnxíng le jiǎnduǎn de hánxuān, qìfēn hěn yǒuhǎo.', 'Sau khi gặp nhau, họ có những lời xã giao ngắn gọn, bầu không khí rất thân thiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-6d85ada319927a73afd71d2f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-86089367e5c5db348e1b0383.mp3'),
    ('宏观', '经济学家从宏观角度分析市场变化。', 'vĩ mô', 'hóng guān', '经济学家从宏观角度分析市场变化。', 'vĩ mô', 'hóng guān', 'Jīngjìxué jiā cóng hóngguān jiǎodù fēnxī shìchǎng biànhuà.', 'Chuyên gia kinh tế phân tích sự biến đổi của thị trường từ góc độ vĩ mô.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-64350ad804632952c0d4ccaf.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-f22642c5ba898607265e9344.mp3'),
    ('宏伟', '这座宏伟的宫殿吸引了无数游客前来参观。', 'to lớn', 'hóng wěi', '这座宏伟的宫殿吸引了无数游客前来参观。', 'to lớn', 'hóng wěi', 'Zhè zuò hóngwěi de gōngdiàn xīyǐn le wúshù yóukè qián lái cānguān.', 'Cung điện to lớn này thu hút vô số khách du lịch đến tham quan.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-3320edd9ee90197f1fd661be.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-ae46acf55272d982a3ae59e4.mp3'),
    ('回顾', '回顾过去，我们学到了很多宝贵的经验。', 'nhìn lại, xem lại (vấn đề), hồi tưởng', 'huí gù', '回顾过去，我们学到了很多宝贵的经验。', 'nhìn lại, xem lại (vấn đề), hồi tưởng', 'huí gù', 'Huígù guòqù, wǒmen xué dào le hěn duō bǎoguì de jīngyàn.', 'Nhìn lại quá khứ, chúng ta đã học được nhiều kinh nghiệm quý báu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-1fe9d18bb48b359dba2fd70f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-79b8f0fb96d00bd1539d74c0.mp3'),
    ('回避', '面对争议，他选择了回避问题而不作回应。', 'né tránh', 'huí bì', '面对争议，他选择了回避问题而不作回应。', 'né tránh', 'huí bì', 'Miànduì zhēngyì, tā xuǎnzé le huíbì wèntí ér bù zuò huíyìng.', 'Đối mặt với tranh cãi, anh ấy chọn tránh né vấn đề mà không phản hồi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-3e8d0ff0d13deb3acdd01554.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-d375afb2a48ea96f8d7f8215.mp3'),
    ('回收', '政府大力推动垃圾回收以保护环境。', 'thu hồi', 'huí shōu', '政府大力推动垃圾回收以保护环境。', 'thu hồi', 'huí shōu', 'Zhèngfǔ dàlì tuīdòng lājī huíshōu yǐ bǎohù huánjìng.', 'Chính phủ tích cực thúc đẩy thu hồi rác thải để bảo vệ môi trường.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-72d2ea240004c26688bf7434.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-75774c53bea3ef651be923c1.mp3')
)
update public.cards as card
set
  pinyin = case
    when card.pinyin = repaired.original_pinyin then repaired.pinyin
    else card.pinyin
  end,
  meaning_vi = case
    when card.meaning_vi = repaired.original_meaning_vi then repaired.meaning_vi
    else card.meaning_vi
  end,
  example_cn = repaired.example_cn,
  example_pinyin = repaired.example_pinyin,
  example_vi = repaired.example_vi,
  word_audio_url = repaired.word_audio_url,
  sentence_audio_url = repaired.sentence_audio_url
from public.decks as deck,
  repaired_hsk as repaired
where card.deck_id = deck.id
  and card.user_id = deck.user_id
  and (
    deck.source_template_slug = 'hsk6-co-ban'
    or (
      deck.source_template_slug is null
      and deck.name = 'HSK6 cơ bản'
    )
  )
  and card.chinese = repaired.chinese
  and (
    card.example_cn is not distinct from repaired.original_example_cn
    or card.example_cn is null
  );
